const createConfigurableAuth = (configPath) => {
  // Scope A
  return (req, res, next) => {
    // Scope B
    const rawConfig = fs.readFileSync(configPath, 'utf-8');
    const config = JSON.parse(rawConfig);

    if (config.allowedIPs.includes(req.ip)) {
      return next();
    }
    res.status(403).send('Forbidden');
  };
};

const app = express();

// Middleware A: Logger
